CREATE TYPE "Role" AS ENUM ('owner', 'admin', 'analyst', 'viewer');
CREATE TYPE "AnalysisState" AS ENUM ('draft', 'waiting_for_documents', 'extracting', 'ready', 'running', 'completed', 'completed_with_warnings', 'failed');
CREATE TYPE "FindingStatus" AS ENUM ('open', 'under_review', 'accepted', 'mitigated', 'false_positive', 'not_applicable');
CREATE TYPE "ExtractionStatus" AS ENUM ('pending', 'completed', 'completed_with_warnings', 'ocr_required', 'failed');
CREATE TYPE "RetentionStatus" AS ENUM ('active', 'scheduled_for_deletion', 'deleted');

CREATE TABLE "User" ("id" UUID NOT NULL, "email" TEXT NOT NULL, "name" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Organization" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Organization_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OrganizationMember" ("id" UUID NOT NULL, "organizationId" UUID NOT NULL, "userId" UUID NOT NULL, "role" "Role" NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "OrganizationMember_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Project" ("id" UUID NOT NULL, "organizationId" UUID NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "primaryCountryCode" VARCHAR(8) NOT NULL, "primarySubdivisionCode" VARCHAR(16), "affectedCountryCodes" TEXT[], "deletedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Project_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AgentProfile" ("id" UUID NOT NULL, "organizationId" UUID NOT NULL, "projectId" UUID NOT NULL, "profile" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AgentProfile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Document" ("id" UUID NOT NULL, "organizationId" UUID NOT NULL, "projectId" UUID NOT NULL, "uploaderId" UUID NOT NULL, "originalFilename" TEXT NOT NULL, "safeFilename" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "size" INTEGER NOT NULL, "checksum" TEXT NOT NULL, "documentType" TEXT NOT NULL, "countryCode" VARCHAR(8) NOT NULL, "subdivisionCode" VARCHAR(16), "storageKey" TEXT NOT NULL, "extractionStatus" "ExtractionStatus" NOT NULL, "extractionError" TEXT, "extractionWarnings" TEXT[], "pageCount" INTEGER, "extractedText" TEXT NOT NULL, "retentionStatus" "RetentionStatus" NOT NULL DEFAULT 'active', "deleteAfter" TIMESTAMP(3), "deletedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Document_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DocumentSegment" ("id" UUID NOT NULL, "organizationId" UUID NOT NULL, "documentId" UUID NOT NULL, "pageNumber" INTEGER, "sectionHeading" TEXT, "paragraphNumber" INTEGER NOT NULL, "characterStart" INTEGER NOT NULL, "characterEnd" INTEGER NOT NULL, "normalizedText" TEXT NOT NULL, "originalText" TEXT NOT NULL, "extractionConfidence" DOUBLE PRECISION NOT NULL, CONSTRAINT "DocumentSegment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Analysis" ("id" UUID NOT NULL, "organizationId" UUID NOT NULL, "projectId" UUID NOT NULL, "agentProfileId" UUID NOT NULL, "state" "AnalysisState" NOT NULL, "engineVersion" TEXT NOT NULL, "rulesetVersions" TEXT[], "jurisdictionPackIds" TEXT[], "attentionScore" JSONB, "warnings" TEXT[], "failureReason" TEXT, "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Analysis_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AnalysisDocument" ("analysisId" UUID NOT NULL, "documentId" UUID NOT NULL, CONSTRAINT "AnalysisDocument_pkey" PRIMARY KEY ("analysisId", "documentId"));
CREATE TABLE "Finding" ("id" UUID NOT NULL, "organizationId" UUID NOT NULL, "analysisId" UUID NOT NULL, "projectId" UUID NOT NULL, "documentId" UUID, "category" TEXT NOT NULL, "severity" TEXT NOT NULL, "confidence" DOUBLE PRECISION NOT NULL, "status" "FindingStatus" NOT NULL DEFAULT 'open', "payload" JSONB NOT NULL, "stableKey" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Finding_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditEvent" ("id" UUID NOT NULL, "organizationId" UUID NOT NULL, "actorId" UUID NOT NULL, "resourceType" TEXT NOT NULL, "resourceId" TEXT NOT NULL, "action" TEXT NOT NULL, "requestId" TEXT NOT NULL, "metadata" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "JurisdictionPackRecord" ("id" TEXT NOT NULL, "countryCode" VARCHAR(8) NOT NULL, "subdivisionCode" VARCHAR(16), "version" TEXT NOT NULL, "status" TEXT NOT NULL, "effectiveDate" TIMESTAMP(3) NOT NULL, "reviewedDate" TIMESTAMP(3), "checksum" TEXT NOT NULL, "payload" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "JurisdictionPackRecord_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE INDEX "OrganizationMember_userId_idx" ON "OrganizationMember"("userId");
CREATE UNIQUE INDEX "OrganizationMember_organizationId_userId_key" ON "OrganizationMember"("organizationId", "userId");
CREATE INDEX "Project_organizationId_createdAt_idx" ON "Project"("organizationId", "createdAt");
CREATE INDEX "Project_organizationId_deletedAt_idx" ON "Project"("organizationId", "deletedAt");
CREATE INDEX "AgentProfile_organizationId_projectId_idx" ON "AgentProfile"("organizationId", "projectId");
CREATE INDEX "Document_organizationId_projectId_createdAt_idx" ON "Document"("organizationId", "projectId", "createdAt");
CREATE INDEX "Document_organizationId_checksum_idx" ON "Document"("organizationId", "checksum");
CREATE INDEX "DocumentSegment_organizationId_documentId_paragraphNumber_idx" ON "DocumentSegment"("organizationId", "documentId", "paragraphNumber");
CREATE INDEX "Analysis_organizationId_projectId_createdAt_idx" ON "Analysis"("organizationId", "projectId", "createdAt");
CREATE INDEX "AnalysisDocument_documentId_idx" ON "AnalysisDocument"("documentId");
CREATE INDEX "Finding_organizationId_analysisId_severity_idx" ON "Finding"("organizationId", "analysisId", "severity");
CREATE UNIQUE INDEX "Finding_analysisId_stableKey_key" ON "Finding"("analysisId", "stableKey");
CREATE INDEX "AuditEvent_organizationId_createdAt_idx" ON "AuditEvent"("organizationId", "createdAt");
CREATE INDEX "AuditEvent_organizationId_resourceType_resourceId_idx" ON "AuditEvent"("organizationId", "resourceType", "resourceId");
CREATE INDEX "JurisdictionPackRecord_countryCode_subdivisionCode_status_idx" ON "JurisdictionPackRecord"("countryCode", "subdivisionCode", "status");
CREATE UNIQUE INDEX "JurisdictionPackRecord_countryCode_subdivisionCode_version_key" ON "JurisdictionPackRecord"("countryCode", "subdivisionCode", "version");

